INSERT INTO dil_yazi_odevleri (dil, seviye, gun, prompt_tr, prompt_hedef, tarih) VALUES
('ingilizce', 'A1', 1, 'Kendini tanıt: adın, yaşın ve nerede yaşadığını yaz.', 'Write 2-3 sentences about yourself. Tell us your name, your age, and where you live.', NULL),
